import { microAlgo } from "@algorandfoundation/algokit-utils";
import { BaseSDK } from "../base";
import { ENV_VAR_NAMES } from "../config";
import {
  AuctionFactoryClient,
  AuctionFactoryFactory,
  AuctionFactoryArgs,
} from '../generated/AuctionFactoryClient';
import { MaybeSigner, NewContractSDKParams } from "../types";
import { AuctionSDK } from "./index";
import {
  NewAuctionParams,
  DeleteAuctionParams,
  CancelAuctionParams,
  OptInParams,
} from "./types";
import { PrizeBoxFactorySDK } from "../prize-box";

export type AuctionFactoryContractArgs = AuctionFactoryArgs["obj"];

/**
 * SDK for interacting with the Auction Factory contract.
 * Used to create new auctions, delete completed auctions, and cancel pending auctions.
 */
export class AuctionFactorySDK extends BaseSDK<AuctionFactoryClient> {

  constructor(params: NewContractSDKParams) {
    super({ factory: AuctionFactoryFactory, ...params }, ENV_VAR_NAMES.AUCTION_FACTORY_APP_ID);
  }

  /**
   * Creates a new auction with an ASA prize and returns an AuctionSDK instance.
   * @returns AuctionSDK for the newly created auction
   */
  async newAuction({
    sender,
    signer,
    isPrizeBox = false,
    name,
    proof,
    bidAssetId,
    bidFee,
    startingBid,
    bidMinimumIncrease,
    startTimestamp,
    endTimestamp,
    gateId,
    marketplace,
    weightsListCount,
    ...rest
  }: NewAuctionParams): Promise<AuctionSDK> {

    const sendParams = this.getRequiredSendParams({ sender, signer });

    const prizeAsset = isPrizeBox ? 0n : (rest as Exclude<NewAuctionParams, { isPrizeBox: true }>).prizeAsset;

    // Get the cost for creating a new auction
    const cost = await this.cost({ isPrizeBox, bidAssetId, prizeAssetId: BigInt(prizeAsset), weightsListCount });

    const payment = await this.client.algorand.createTransaction.payment({
      ...sendParams,
      amount: microAlgo(cost),
      receiver: this.client.appAddress,
    });

    let appId: bigint | undefined;
    
    if (isPrizeBox) {
      const { prizeBoxId } = rest as Exclude<NewAuctionParams, { isPrizeBox: false }>;

      const prizeBoxSDK = new PrizeBoxFactorySDK({ algorand: this.algorand, factoryParams: {}}).get({ appId: BigInt(prizeBoxId) })
      const prizeBoxTransferTxn = (await prizeBoxSDK.client.createTransaction.transfer({
        sender,
        signer,
        args: {
          newOwner: this.client.appAddress.toString()
        }
      })).transactions[0];

      ({ return: appId } = await this.client.send.newPrizeBoxAuction({
        ...sendParams,
        args: {
          prizeBoxTransferTxn,
          payment,
          bidAssetId,
          bidFee,
          startingBid,
          bidMinimumIncrease,
          startTimestamp,
          endTimestamp,
          gateId,
          marketplace,
          weightsListCount,
        },
      }));
    } else {
      const { prizeAsset, prizeAmount } = rest as Exclude<NewAuctionParams, { isPrizeBox: true }>;

      const assetXfer = await this.client.algorand.createTransaction.assetTransfer({
        ...sendParams,
        amount: BigInt(prizeAmount),
        assetId: BigInt(prizeAsset),
        receiver: this.client.appAddress,
      });

      ({ return: appId } = await this.client.send.newAuction({
        ...sendParams,
        args: {
          payment,
          assetXfer,
          name,
          proof,
          bidAssetId,
          bidFee,
          startingBid,
          bidMinimumIncrease,
          startTimestamp,
          endTimestamp,
          gateId,
          marketplace,
          weightsListCount,
        },
      }));
    }

    if (appId === undefined) {
      throw new Error('Failed to create new auction');
    }

    return new AuctionSDK({
      algorand: this.algorand,
      factoryParams: {
        appId,
        defaultSender: sendParams.sender,
        defaultSigner: sendParams.signer,
      },
    });
  }

  /**
   * Gets an AuctionSDK instance for an existing auction.
   * @param appId - The app ID of the auction
   * @returns AuctionSDK for the specified auction
   */
  get({ appId }: { appId: bigint }): AuctionSDK {
    return new AuctionSDK({
      algorand: this.algorand,
      factoryParams: {
        appId,
        defaultSender: this.sendParams.sender,
        defaultSigner: this.sendParams.signer,
      },
    });
  }

  /**
   * Gets the cost to create a new auction.
   */
  async cost({ isPrizeBox, bidAssetId, prizeAssetId, weightsListCount }: AuctionFactoryArgs['obj']['newAuctionCost(bool,uint64,uint64,uint64)uint64']): Promise<bigint> {
    return await this.client.newAuctionCost({ args: { isPrizeBox, bidAssetId, prizeAssetId, weightsListCount } });
  }

  async optIn({ sender, signer, asset }: OptInParams): Promise<void> {
    const sendParams = this.getRequiredSendParams({ sender, signer });

    const cost = await this.client.optInCost({ args: { asset } })

    const payment = await this.client.algorand.createTransaction.payment({
      ...sendParams,
      amount: microAlgo(cost),
      receiver: this.client.appAddress,
    });

    await this.client.send.optIn({
      ...sendParams,
      args: { payment, asset },
      maxFee: microAlgo(257_000),
      coverAppCallInnerTransactionFees: true,
      populateAppCallResources: true,
    });
  }

  /**
   * Deletes an auction after all cleanup is complete.
   * Can only be called after prize is claimed, raffle prize is claimed, and all MBR is refunded.
   */
  async deleteAuction({ sender, signer, appId }: DeleteAuctionParams): Promise<void> {
    const sendParams = this.getSendParams({ sender, signer });

    await this.client.send.deleteAuctionApp({
      ...sendParams,
      args: { appId },
    });
  }

  /**
   * Cancels an auction before it starts.
   * Returns the prize and MBR to the seller.
   */
  async cancelAuction({ sender, signer, appId }: CancelAuctionParams): Promise<void> {
    const sendParams = this.getSendParams({ sender, signer });

    await this.client.send.cancelAuction({
      ...sendParams,
      args: { appId },
    });
  }

  /**
   * Updates the Akita DAO reference.
   */
  async updateAkitaDAO({ sender, signer, akitaDao }: MaybeSigner & AuctionFactoryContractArgs['updateAkitaDAO(uint64)void']): Promise<void> {
    const sendParams = this.getSendParams({ sender, signer });

    await this.client.send.updateAkitaDao({
      ...sendParams,
      args: { akitaDao },
    });
  }

  /**
   * Updates the Akita DAO Escrow reference.
   */
  async updateAkitaDAOEscrow({ sender, signer, config }: MaybeSigner & AuctionFactoryContractArgs['updateAkitaDAOEscrow((string,uint64))void']): Promise<void> {
    const sendParams = this.getSendParams({ sender, signer });

    await this.client.send.updateAkitaDaoEscrow({
      ...sendParams,
      args: { config },
    });
  }
}

/**
 * Convenience function to create a new auction and return the SDK.
 * Creates a factory SDK, creates the auction, and returns the auction SDK.
 */
export async function newAuction({
  factoryParams,
  algorand,
  readerAccount,
  sendParams,
  ...auctionParams
}: NewContractSDKParams & NewAuctionParams): Promise<AuctionSDK> {
  const factory = new AuctionFactorySDK({ factoryParams, algorand, readerAccount, sendParams });
  return await factory.newAuction(auctionParams);
}
